<table class="enterprise-table" <?=$recipeFilters?'data-butchery-history="recipes"':''?> data-search-placeholder="Code, fiche, matière…"><thead><tr><th>Code / fiche</th><th>Version</th><th>Composition</th><th>Applicable depuis</th><th>Statut</th><th>Détail</th></tr></thead><tbody><?php foreach($recipeRows as $row):$state=$recipeStatus($row);?><tr data-status="<?=e($state)?>" data-date="<?=e($row['effective_from'])?>"><td><strong><?=e($row['code'])?></strong><small><?=e($row['name'])?></small></td><td data-order="<?=e($row['version_number'])?>">v<?=e($row['version_number'])?></td><td><?php foreach($components[$row['id']]??[] as $line):?><small><?=e($line['item_name'].' · '.number_format((float)$line['percentage'],3,',',' ').' %')?></small><?php endforeach;?></td><td data-order="<?=e(strtotime($row['effective_from']))?>"><?=e(date('d/m/Y',strtotime($row['effective_from'])))?></td><td><span class="butchery-status <?=$state==='active'?'butchery-status-success':'butchery-status-muted'?>"><?=e($recipeLabels[$state])?></span></td><td><button class="btn-secondary" type="button" data-workspace-modal-open="recipe-detail-<?=e($row['id'])?>" aria-label="<?=e('Consulter '.$row['code'].' version '.$row['version_number'])?>">Consulter</button></td></tr><?php endforeach;?></tbody></table>
